<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= esc($receipt['receipt_number']) ?> | Sun Son Solar</title><style>body{font:16px/1.5 Arial,sans-serif;color:#17231f;margin:0;background:#f3f5f1}.receipt{max-width:700px;margin:48px auto;background:#fff;padding:40px;border:1px solid #dce4dc;border-radius:12px}.head{display:flex;justify-content:space-between;border-bottom:2px solid #d1ed73;padding-bottom:20px}.muted{color:#718078}.line{display:flex;justify-content:space-between;padding:12px 0;border-bottom:1px solid #e6ebe5}.total{font-size:22px;font-weight:bold}.actions{margin-top:25px}@media print{body{background:white}.receipt{margin:0 auto;border:0}.actions{display:none}}</style></head><body><main class="receipt"><div class="head"><div><h1>Sun Son Solar</h1><p class="muted">Payment receipt</p></div><div><b><?= esc($receipt['receipt_number']) ?></b><br><span class="muted">Issued <?= esc($receipt['issued_at']) ?></span></div></div><p><b>Received from</b><br><?= esc($receipt['first_name'].' '.$receipt['last_name']) ?></p><p><b>Service</b><br><?= esc($receipt['service_name']) ?><br><?= esc($receipt['address']) ?></p><div class="line"><span>Payment date</span><span><?= esc($receipt['paid_at']??'—') ?></span></div><div class="line"><span>Payment reference</span><span><?= esc($receipt['reference']??'—') ?></span></div><div class="line total"><span>Amount paid</span><span><?= number_format((float)$receipt['amount'],2) ?></span></div><div class="actions"><button onclick="window.print()">Print / Save as PDF</button> <a href="<?= site_url('dashboard') ?>">Back to dashboard</a> · <a href="<?= base_url('intro.html') ?>">Public site</a></div></main></body></html>
